/// BUG: uses approximate PI instead of std::f64::consts::PI
pub fn circle_area(r: f64) -> f64 {
    3.14 * r * r
}

/// BUG: missing parentheses — computes 2w + h instead of 2(w + h)
pub fn rectangle_perimeter(w: f64, h: f64) -> f64 {
    2.0 * w + h
}

/// BUG: adds a and b before sqrt instead of squaring them
pub fn triangle_hypotenuse(a: f64, b: f64) -> f64 {
    (a + b).sqrt()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::f64::consts::PI;

    #[test]
    fn test_circle_area() {
        // 3.14 * 4.0 = 12.56, but PI * 4.0 ≈ 12.566 — fails tolerance
        assert!((circle_area(2.0) - PI * 4.0).abs() < 0.001,
            "circle_area(2.0) = {} but expected ~{}", circle_area(2.0), PI * 4.0);
    }

    #[test]
    fn test_rectangle_perimeter() {
        // 2.0*3.0 + 4.0 = 10.0, should be 2*(3+4) = 14.0
        assert_eq!(rectangle_perimeter(3.0, 4.0), 14.0);
    }

    #[test]
    fn test_triangle_hypotenuse() {
        // sqrt(3+4) ≈ 2.65, should be sqrt(9+16) = 5.0
        assert!((triangle_hypotenuse(3.0, 4.0) - 5.0).abs() < 0.001,
            "hypotenuse(3,4) = {} but expected 5.0", triangle_hypotenuse(3.0, 4.0));
    }
}

task_spec.prompt:
Fix the three bugs in src/lib.rs:

1. circle_area: replace the hardcoded 3.14 with std::f64::consts::PI
   use std::f64::consts::PI;
   pub fn circle_area(r: f64) -> f64 { PI * r * r }

2. rectangle_perimeter: add the missing parentheses
   pub fn rectangle_perimeter(w: f64, h: f64) -> f64 { 2.0 * (w + h) }

3. triangle_hypotenuse: square a and b before summing and taking the square root
   pub fn triangle_hypotenuse(a: f64, b: f64) -> f64 { (a * a + b * b).sqrt() }

All 3 tests must pass.
Run: cargo test
